--
-- Table structure for table `tb_payment_transactions`
--

DROP TABLE IF EXISTS `tb_payment_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tb_payment_transactions` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `payment_ID` int unsigned NOT NULL,
  `transaction_type` enum('Charge','Refund','Authorization','Void') NOT NULL DEFAULT 'Charge',
  `amount` decimal(10,2) NOT NULL DEFAULT '0.00',
  `currency` varchar(3) NOT NULL DEFAULT 'MXN',
  `gateway_transaction_id` varchar(255) DEFAULT NULL,
  `gateway_response` text,
  `operation_status` enum('Pending','Completed','Failed','Cancelled') NOT NULL DEFAULT 'Pending',
  `status` bit(1) NOT NULL DEFAULT b'1',
  `creation_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `last_update` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `idx_payment_transactions_payment` (`payment_ID`),
  CONSTRAINT `fk_payment_transactions_payment` FOREIGN KEY (`payment_ID`) REFERENCES `tbd_payments` (`payment_ID`),
  CONSTRAINT `chk_transaction_amount` CHECK ((`amount` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

