/*!50003 CREATE*/ /*!50017 DEFINER=`jose.castillo`@`%`*/ /*!50003 TRIGGER `trg_tb_payment_transactions_after_update` AFTER UPDATE ON `tb_payment_transactions` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.`ID` <=> NEW.`ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('ID: [',COALESCE(CAST(OLD.`ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`payment_ID` <=> NEW.`payment_ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('payment_ID: [',COALESCE(CAST(OLD.`payment_ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`payment_ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`transaction_type` <=> NEW.`transaction_type`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('transaction_type: [',COALESCE(CAST(OLD.`transaction_type` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`transaction_type` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`amount` <=> NEW.`amount`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('amount: [',COALESCE(CAST(OLD.`amount` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`amount` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`currency` <=> NEW.`currency`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('currency: [',COALESCE(CAST(OLD.`currency` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`currency` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`gateway_transaction_id` <=> NEW.`gateway_transaction_id`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('gateway_transaction_id: [',COALESCE(CAST(OLD.`gateway_transaction_id` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`gateway_transaction_id` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`gateway_response` <=> NEW.`gateway_response`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('gateway_response: [',COALESCE(CAST(OLD.`gateway_response` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`gateway_response` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`operation_status` <=> NEW.`operation_status`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('operation_status: [',COALESCE(CAST(OLD.`operation_status` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`operation_status` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`status`+0 <=> NEW.`status`+0) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('status: [',COALESCE(CAST(OLD.`status`+0 AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`status`+0 AS CHAR),'NULL'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tb_payment_transactions','Update',USER(),CONCAT('Transacción de pago actualizado/a. ID=',NEW.`ID`,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
