/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_user_addresses_after_update` AFTER UPDATE ON `tb_user_addresses` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.`ID` <=> NEW.`ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('ID: [',COALESCE(CAST(OLD.`ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`user_ID` <=> NEW.`user_ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('user_ID: [',COALESCE(CAST(OLD.`user_ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`user_ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`address_label` <=> NEW.`address_label`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('address_label: [',COALESCE(CAST(OLD.`address_label` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`address_label` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`recipient_name` <=> NEW.`recipient_name`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('recipient_name: [',COALESCE(CAST(OLD.`recipient_name` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`recipient_name` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`recipient_phone` <=> NEW.`recipient_phone`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('recipient_phone: [',COALESCE(CAST(OLD.`recipient_phone` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`recipient_phone` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`delivery_instructions` <=> NEW.`delivery_instructions`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('delivery_instructions: [',COALESCE(CAST(OLD.`delivery_instructions` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`delivery_instructions` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`latitude` <=> NEW.`latitude`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('latitude: [',COALESCE(CAST(OLD.`latitude` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`latitude` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`longitude` <=> NEW.`longitude`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('longitude: [',COALESCE(CAST(OLD.`longitude` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`longitude` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`is_default` <=> NEW.`is_default`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('is_default: [',COALESCE(CAST(OLD.`is_default` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`is_default` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`status` <=> NEW.`status`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('status: [',IF(COALESCE(OLD.`status`,b'0')=b'1','Activo','Inactivo'),'] -> [',IF(COALESCE(NEW.`status`,b'0')=b'1','Activo','Inactivo'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tb_user_addresses','Update',USER(),CONCAT('Dirección de usuario actualizado/a. ID=',NEW.`ID`,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
