/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_users_after_update` AFTER UPDATE ON `tb_users` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.email <=> NEW.email) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('email: [',OLD.email,'] -> [',NEW.email,']')); END IF;
  IF NOT (OLD.nickname <=> NEW.nickname) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('nickname: [',OLD.nickname,'] -> [',NEW.nickname,']')); END IF;
  IF NOT (OLD.last_login <=> NEW.last_login) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('last_login: [',COALESCE(CAST(OLD.last_login AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.last_login AS CHAR),'NULL'),']')); END IF;
  IF v_cambios <> '' THEN
    INSERT INTO `tb_logs` (`table_name`,`operation`,`db_user`,`description`,`operation_date`,`operation_status`)
    VALUES ('tb_users','Update',USER(),CONCAT('Usuario actualizado. ID=',NEW.ID,'. Cambios: ',v_cambios),CURRENT_TIMESTAMP,b'1');
  END IF;
END */;;
DELIMITER ;
