/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tbb_orders_after_update` AFTER UPDATE ON `tbb_orders` FOR EACH ROW BEGIN
  DECLARE v_cambios TEXT DEFAULT '';
  IF NOT (OLD.`ID` <=> NEW.`ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('ID: [',COALESCE(CAST(OLD.`ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`key` <=> NEW.`key`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('key: [',COALESCE(CAST(OLD.`key` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`key` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`User_ID` <=> NEW.`User_ID`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('User_ID: [',COALESCE(CAST(OLD.`User_ID` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`User_ID` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`total_products` <=> NEW.`total_products`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('total_products: [',COALESCE(CAST(OLD.`total_products` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`total_products` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`total_cost` <=> NEW.`total_cost`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('total_cost: [',COALESCE(CAST(OLD.`total_cost` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`total_cost` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`status_string` <=> NEW.`status_string`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('status_string: [',COALESCE(CAST(OLD.`status_string` AS CHAR),'NULL'),'] -> [',COALESCE(CAST(NEW.`status_string` AS CHAR),'NULL'),']')); END IF;
  IF NOT (OLD.`status` <=> NEW.`status`) THEN SET v_cambios=CONCAT_WS('; ',NULLIF(v_cambios,''),CONCAT('status: [',IF(COALESCE(OLD.`status`,b'0')=b'1','Activo','Inactivo'),'] -> [',IF(COALESCE(NEW.`status`,b'0')=b'1','Activo','Inactivo'),']')); END IF;
