  SET v = REPLACE(v, 'ô', 'o');
  SET v = REPLACE(v, 'ö', 'o');
  SET v = REPLACE(v, 'õ', 'o');
  SET v = REPLACE(v, 'ø', 'o');
  SET v = REPLACE(v, 'ú', 'u');
  SET v = REPLACE(v, 'ù', 'u');
  SET v = REPLACE(v, 'û', 'u');
  SET v = REPLACE(v, 'ü', 'u');
  SET v = REPLACE(v, 'ñ', 'n');
  SET v = REPLACE(v, 'ç', 'c');
  SET v = REPLACE(v, 'ß', 'ss');
  SET v = REGEXP_REPLACE(v, '[^a-z0-9]', '');
  RETURN v;
END ;;
DELIMITER ;
