CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_birth_date`(p_min_age TINYINT UNSIGNED, p_max_age TINYINT UNSIGNED) RETURNS date
    NO SQL
BEGIN
  DECLARE v_from DATE DEFAULT DATE_ADD(DATE_SUB(CURDATE(), INTERVAL (p_max_age + 1) YEAR), INTERVAL 1 DAY);
  DECLARE v_to   DATE DEFAULT DATE_SUB(CURDATE(), INTERVAL p_min_age YEAR);
  RETURN DATE_ADD(v_from, INTERVAL fn_gen_rand_int(0, DATEDIFF(v_to, v_from)) DAY);
END ;;
DELIMITER ;
