CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_country_culture`(p_country CHAR(2) CHARSET utf8mb4) RETURNS char(2) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
  RETURN CASE
    WHEN p_country IN ('US', 'CA', 'GB', 'AU') THEN 'EN'
    WHEN p_country IN ('MX', 'ES', 'AR', 'CO', 'CL', 'PE') THEN 'ES'
    WHEN p_country IN ('BR', 'PT') THEN 'PT'
    WHEN p_country IN ('FR') THEN 'FR'
    WHEN p_country IN ('DE') THEN 'DE'
    WHEN p_country IN ('IT') THEN 'IT'
    WHEN p_country IN ('JP') THEN 'JA'
    WHEN p_country IN ('IN') THEN 'HI'
    ELSE NULL
  END;
END ;;
DELIMITER ;
