CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_gender`() RETURNS varchar(19) CHARSET utf8mb4
    NO SQL
BEGIN
  DECLARE v_r DOUBLE DEFAULT RAND();
  RETURN CASE WHEN v_r < 0.49 THEN 'Masculino' WHEN v_r < 0.98 THEN 'Femenino' ELSE 'Prefiero no decirlo' END;
END ;;
