CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_password`(p_length TINYINT UNSIGNED) RETURNS varchar(64) CHARSET utf8mb4
    NO SQL
BEGIN
  DECLARE v_chars VARCHAR(60) DEFAULT 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  DECLARE v_pwd   VARCHAR(64) DEFAULT '';
  DECLARE v_i     TINYINT UNSIGNED DEFAULT 0;
  WHILE v_i < p_length DO
    SET v_pwd = CONCAT(v_pwd, SUBSTRING(v_chars, fn_gen_rand_int(1, CHAR_LENGTH(v_chars)), 1));
    SET v_i = v_i + 1;
  END WHILE;
  RETURN v_pwd;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
