CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_phone`(p_country CHAR(2) CHARSET utf8mb4) RETURNS varchar(25) CHARSET utf8mb4
    NO SQL
BEGIN
  RETURN CASE p_country
    WHEN 'US' THEN CONCAT('+1', fn_gen_rand_int(2,9), fn_gen_random_digits(2), fn_gen_rand_int(2,9), fn_gen_random_digits(6))
    WHEN 'CA' THEN CONCAT('+1', fn_gen_rand_int(2,9), fn_gen_random_digits(2), fn_gen_rand_int(2,9), fn_gen_random_digits(6))
    WHEN 'GB' THEN CONCAT('+447', fn_gen_random_digits(9))
    WHEN 'AU' THEN CONCAT('+614', fn_gen_random_digits(8))
    WHEN 'MX' THEN CONCAT('+52', fn_gen_rand_int(2,9), fn_gen_random_digits(9))
    WHEN 'ES' THEN CONCAT('+34', fn_gen_rand_int(6,7), fn_gen_random_digits(8))
    WHEN 'AR' THEN CONCAT('+549', fn_gen_random_digits(10))
    WHEN 'CO' THEN CONCAT('+573', fn_gen_random_digits(9))
    WHEN 'CL' THEN CONCAT('+569', fn_gen_random_digits(8))
    WHEN 'PE' THEN CONCAT('+519', fn_gen_random_digits(8))
    WHEN 'BR' THEN CONCAT('+55', fn_gen_rand_int(11,99), '9', fn_gen_random_digits(8))
    WHEN 'PT' THEN CONCAT('+3519', fn_gen_random_digits(8))
    WHEN 'FR' THEN CONCAT('+33', fn_gen_rand_int(6,7), fn_gen_random_digits(8))
    WHEN 'DE' THEN CONCAT('+491', fn_gen_rand_int(5,7), fn_gen_random_digits(9))
    WHEN 'IT' THEN CONCAT('+393', fn_gen_random_digits(9))
    WHEN 'JP' THEN CONCAT('+81', ELT(fn_gen_rand_int(1,3),'70','80','90'), fn_gen_random_digits(8))
    WHEN 'IN' THEN CONCAT('+91', fn_gen_rand_int(6,9), fn_gen_random_digits(9))
    ELSE NULL
  END;
END ;;
DELIMITER ;
