CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_random_country`() RETURNS char(2) CHARSET utf8mb4
    NO SQL
BEGIN
  RETURN ELT(fn_gen_rand_int(1,17), 'US', 'CA', 'GB', 'AU', 'MX', 'ES', 'AR', 'CO', 'CL', 'PE', 'BR', 'PT', 'FR', 'DE', 'IT', 'JP', 'IN');
END ;;
