CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_random_digits`(p_n TINYINT UNSIGNED) RETURNS varchar(20) CHARSET utf8mb4
    NO SQL
BEGIN
  RETURN LPAD(CAST(FLOOR(RAND() * POW(10, p_n)) AS CHAR), p_n, '0');
