CREATE DEFINER=`root`@`localhost` FUNCTION `fn_gen_rand_int`(p_min INT, p_max INT) RETURNS int
    NO SQL
BEGIN
  RETURN FLOOR(p_min + RAND() * (p_max - p_min + 1));
END ;;
