DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_deactivate_users_in_range`(
  IN p_first_user_ID INT UNSIGNED,
  IN p_last_user_ID  INT UNSIGNED,
  IN p_percent       TINYINT UNSIGNED
)
    MODIFIES SQL DATA
BEGIN
  DECLARE v_active INT UNSIGNED;
  DECLARE v_target INT UNSIGNED;

  IF p_first_user_ID IS NULL OR p_last_user_ID IS NULL OR p_first_user_ID > p_last_user_ID THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Rango de usuarios invalido.';
  END IF;
  IF p_percent IS NULL OR p_percent > 100 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El porcentaje debe estar entre 0 y 100.';
  END IF;

  SELECT COUNT(*) INTO v_active
    FROM tb_users
   WHERE ID BETWEEN p_first_user_ID AND p_last_user_ID AND status = b'1';

  SET v_target = ROUND(v_active * p_percent / 100);

  UPDATE tb_users
     SET status = b'0'
   WHERE ID BETWEEN p_first_user_ID AND p_last_user_ID AND status = b'1'
   ORDER BY RAND()
   LIMIT v_target;

  UPDATE tb_people p
    JOIN tb_users u ON u.ID = p.user_ID
     SET p.status = b'0'
   WHERE u.ID BETWEEN p_first_user_ID AND p_last_user_ID
     AND u.status = b'0' AND p.status = b'1';
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
