CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_mixed_status_users`(IN p_quantity INT UNSIGNED, IN p_inactive_percent TINYINT UNSIGNED)
    MODIFIES SQL DATA
BEGIN
  DECLARE v_first INT UNSIGNED; DECLARE v_last INT UNSIGNED; DECLARE v_created INT UNSIGNED;
  CALL sp_generate_users(p_quantity, NULL, 18, 65, NULL, v_first, v_last, v_created);
  CALL sp_deactivate_users_in_range(v_first, v_last, p_inactive_percent);
  CALL sp_summarize_user_batch(v_first, v_last);
END ;;
