CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_users`(
  IN  p_quantity         INT UNSIGNED,
  IN  p_country_code     CHAR(2),
  IN  p_min_age          TINYINT UNSIGNED,
  IN  p_max_age          TINYINT UNSIGNED,
  IN  p_default_password VARCHAR(255),
  OUT p_first_user_ID    INT UNSIGNED,
  OUT p_last_user_ID     INT UNSIGNED,
  OUT p_created          INT UNSIGNED
)
    MODIFIES SQL DATA
BEGIN
  DECLARE v_created      INT UNSIGNED DEFAULT 0;
  DECLARE v_attempts     INT UNSIGNED DEFAULT 0;
  DECLARE v_max_attempts INT UNSIGNED;
  DECLARE v_seq          BIGINT UNSIGNED;
  DECLARE v_country      CHAR(2);
  DECLARE v_culture      CHAR(2);
  DECLARE v_gender       VARCHAR(19);
  DECLARE v_given        VARCHAR(60);
  DECLARE v_family       VARCHAR(100);
  DECLARE v_family1      VARCHAR(60);
  DECLARE v_user_id      INT UNSIGNED;
  DECLARE v_person_id    BIGINT UNSIGNED;

  
  IF p_quantity IS NULL OR p_quantity = 0 OR p_quantity > 100000 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cantidad debe estar entre 1 y 100000.';
  END IF;
  IF p_min_age IS NULL OR p_max_age IS NULL OR p_min_age < 18 OR p_max_age > 99 OR p_min_age > p_max_age THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Rango de edad invalido (use 18 a 99 y min <= max).';
  END IF;
  IF p_country_code IS NOT NULL AND fn_gen_country_culture(UPPER(p_country_code)) IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pais no soportado por el generador.';
  END IF;
  IF p_default_password IS NOT NULL AND CHAR_LENGTH(p_default_password) < 8 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La contrasena fija debe tener al menos 8 caracteres.';
  END IF;

  SET p_first_user_ID = NULL;
  SET p_last_user_ID  = NULL;
  SET v_max_attempts  = p_quantity * 2 + 10;
  SET v_seq           = (SELECT IFNULL(MAX(ID), 0) FROM tb_users);

  BEGIN
    
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;

    WHILE v_created < p_quantity AND v_attempts < v_max_attempts DO
      SET v_attempts = v_attempts + 1;
      SET v_seq      = v_seq + 1;

      SET v_country  = COALESCE(UPPER(p_country_code), fn_gen_random_country());
      SET v_culture  = fn_gen_country_culture(v_country);
      SET v_gender   = fn_gen_gender();
      SET v_given    = fn_gen_first_name(v_culture, v_gender);
      SET v_family   = fn_gen_family_name(v_culture);
      SET v_family1  = SUBSTRING_INDEX(v_family, ' ', 1);
      SET v_user_id  = NULL;
      SET v_person_id = NULL;

      CALL sp_register_user(
        fn_gen_email(v_given, v_family1, v_seq),
        fn_gen_nickname(v_given, v_family1, v_seq),
        COALESCE(p_default_password, fn_gen_password(12)),
        fn_gen_courtesy_title(v_gender),
        v_given,
        v_family,
        fn_gen_birth_date(p_min_age, p_max_age),
        v_gender,
        v_country,
        fn_gen_phone(v_country),
        v_user_id,
        v_person_id
      );

      IF v_user_id IS NOT NULL THEN
        SET v_created = v_created + 1;
        IF p_first_user_ID IS NULL THEN SET p_first_user_ID = v_user_id; END IF;
        SET p_last_user_ID = v_user_id;
      END IF;
    END WHILE;
  END;

  SET p_created = v_created;
  IF v_created < p_quantity THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'No se pudieron crear todos los usuarios solicitados; revise tb_users/tb_logs.';
  END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `sp_generate_us_users` */;
