/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_summarize_user_batch`(IN p_first_user_ID INT UNSIGNED, IN p_last_user_ID INT UNSIGNED)
    READS SQL DATA
BEGIN
  SELECT p_first_user_ID                                   AS primer_user_ID,
         p_last_user_ID                                    AS ultimo_user_ID,
         COUNT(*)                                          AS usuarios,
         COUNT(DISTINCT pe.country_code)                   AS paises,
         MIN(TIMESTAMPDIFF(YEAR, pe.birth_date, CURDATE())) AS edad_min,
         MAX(TIMESTAMPDIFF(YEAR, pe.birth_date, CURDATE())) AS edad_max,
         SUM(u.status + 0)                                 AS activos,
         SUM(1 - (u.status + 0))                           AS dados_de_baja,
         ROUND(100 * SUM(u.status + 0) / COUNT(*), 2)      AS pct_activos
    FROM tb_users u
    JOIN tb_people pe ON pe.user_ID = u.ID
   WHERE u.ID BETWEEN p_first_user_ID AND p_last_user_ID;
END ;;
DELIMITER ;
